function lesson6Dialogue(){app.innerHTML=intro('HỘI THOẠI · BÀI 6','Kể về chuyến đi cuối tuần trước.','Hai hội thoại được chép lại từ các trang bạn gửi.')+lesson2VoiceControls()+'<button class="btn secondary" id="pinyin">'+(showPinyin?'Ẩn':'Hiện')+' pinyin</button>'+lesson6Data.dialogues.map(([title,lines],d)=>'<h2>'+title+'</h2><button class="btn secondary" data-lesson6-full="'+d+'">▶ Nghe toàn hội thoại</button>'+lines.map(([name,zh,py,vi],i)=>'<article class="dialogue"><small>'+name+'</small><button class="text-button" data-lesson6-line="'+d+','+i+'" aria-label="Nghe câu '+(i+1)+'">▶</button><p class="han">'+zh+'</p>'+(showPinyin?'<p class="pinyin">'+py+'</p>':'')+'<p>'+vi+'</p></article>').join('')).join('')+lesson6References(6,9);bindLesson2Voice(lesson6Data.dialogues[0][1].map(l=>l[1]).join(' '));document.querySelector('#pinyin').onclick=()=>{stopWordAudio();showPinyin=!showPinyin;lesson6Dialogue();};document.querySelectorAll('[data-lesson6-line]').forEach(b=>b.onclick=()=>{const[d,i]=b.dataset.lesson6Line.split(',').map(Number);lesson2Speak(lesson6Data.dialogues[d][1][i][1]);});document.querySelectorAll('[data-lesson6-full]').forEach(b=>b.onclick=()=>lesson2Speak(lesson6Data.dialogues[Number(b.dataset.lesson6Full)][1].map(l=>l[1]).join(' ')));}
function lesson6BTNCMarkup(file){const group=lesson6BTNC.find(g=>g.file===file);if(!group)return '<p class="sub">File chính Q2B6; xem phần đáp án BTNC trên trang tham khảo bên dưới.</p>'+lesson6BTNCReference();const id=lesson6BTNC.indexOf(group),saved=state.lesson6Exercises?.['btnc'+id]||{};return '<details class="lesson2-answer-key"><summary>Luyện nghe với 5 câu hỏi</summary><p class="sub">Câu hỏi tự luyện biên soạn từ bản ghi lời nghe, không phải bộ lựa chọn của đề BTNC gốc.</p><form id="lesson6BTNCForm'+id+'">'+group.questions.map((q,i)=>'<fieldset class="question"><legend>'+q[0]+'</legend>'+q[1].map((v,j)=>'<label><input type="radio" name="l6nc'+id+'q'+i+'" value="'+j+'" '+(String(saved[i]?.answer)===String(j)?'checked':'')+'> '+v+'</label>').join('')+'<div id="lesson6BTNCFeedback'+id+'-'+i+'"></div></fieldset>').join('')+'<button class="btn" type="submit">Kiểm tra</button><p id="lesson6BTNCResult'+id+'" role="status"></p></form></details><details class="lesson2-answer-key"><summary>Bản ghi lời nghe và đáp án BTNC gốc</summary>'+group.transcript.map((t,i)=>'<p lang="zh-CN" style="white-space:pre-line">'+(i+1)+'. '+esc(t)+'</p>').join('')+'<p><b>Đáp án '+group.title+':</b> '+group.key.map((k,i)=>(i+1)+'. '+k).join(' · ')+'</p><p class="sub">Các chữ cái dùng đối chiếu với đề BTNC gốc; câu tự luyện phía trên có thứ tự lựa chọn riêng.</p>'+lesson6BTNCReference()+'</details>';}
function lesson6BTNCReference(){return '<details class="lesson2-reference"><summary>Xem trang đáp án BTNC bài 6</summary><img loading="lazy" style="max-width:100%;height:auto" src="images/lesson6/btnc-answers-page17.png" alt="Đáp án BTNC bài 6, trang 17 của PDF"></details>';}
function bindLesson6BTNC(){lesson6BTNC.forEach((group,id)=>{document.querySelector('#lesson6BTNCForm'+id).onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),records={};let count=0;group.questions.forEach((q,i)=>{const answer=form.get('l6nc'+id+'q'+i),correct=answer!==null&&Number(answer)===q[2];records[i]={answer,correct};count+=correct?1:0;document.querySelector('#lesson6BTNCFeedback'+id+'-'+i).innerHTML='<div class="feedback '+(correct?'good':'bad')+'">'+(correct?'✓ Chính xác':'Đáp án: '+esc(q[1][q[2]]))+'</div>';});state.lesson6Exercises=state.lesson6Exercises||{};state.lesson6Exercises['btnc'+id]=records;save();document.querySelector('#lesson6BTNCResult'+id).textContent='Đúng '+count+' / 5 câu.';};});}

const lesson6SourcePages=['65','66','67','68','69','70','71','72','73','74','75','76'];
function lesson6References(first=1,last=12){return '<details class="lesson2-reference"><summary>Xem trang giáo trình gốc</summary>'+Array.from({length:last-first+1},(_,i)=>'<figure><img loading="lazy" src="images/lesson6/source-'+(first+i)+'.png" alt="Bài 6 · ảnh nguồn '+(first+i)+'"><figcaption>Trang '+lesson6SourcePages[first+i-1]+'</figcaption></figure>').join('')+'</details>';}
function lesson6Home(){app.innerHTML=intro('HSK2 · LESSON 6',lesson6Data.title,lesson6Data.pinyin+' · '+lesson6Data.vi)+'<section class="hero"><div><h2>Kể chuyện cuối tuần trước</h2><p>Nói về việc đã làm, tham quan bảo tàng và công viên.</p><a class="btn" href="#words">Học 19 mục từ →</a></div><div class="hero-mark" aria-hidden="true">游</div></section><div class="stats"><div class="stat"><small>TỪ ĐÃ NHỚ</small><strong>'+state.known.length+'<small> / 19</small></strong></div><div class="stat"><small>HỘI THOẠI</small><strong>02</strong></div><div class="stat"><small>TRANG GIÁO TRÌNH</small><strong>65–76</strong></div></div><div class="grid">'+[['words','Từ vựng','Nghe & gõ · Flashcard · Ghép từ'],['grammar','Ngữ pháp','了 và 没 · Câu vị ngữ chủ vị'],['dialogue','Hội thoại','Tham quan bảo tàng · Chụp ảnh công viên'],['practice','Luyện tập','Điền từ · Đọc hiểu · Hỏi việc đã làm'],['listening','Luyện nghe','Bốn file Q2B6 · Bản ghi BTNC · Tự luyện'],['writing','Luyện viết','Chữ Hán trong bài 6']].map(([id,title,desc])=>'<a class="card card-link" href="#'+id+'"><h3>'+title+' ↗</h3><p>'+desc+'</p></a>').join('')+'</div><article class="card grammar"><h2>Khởi động</h2><p>你周末常常一个人做什么？<br>你周末跟朋友一起做什么？<br>上个周末你做什么了？</p></article>'+lesson6References();}
function lesson6Grammar(){app.innerHTML=intro('NGỮ PHÁP · BÀI 6','Kể về việc đã xảy ra.','了 chỉ sự việc xảy ra hoặc hoàn thành; 没 phủ định hành động trong các mẫu của bài.')+`<article class="card grammar"><h2>01 · 了 chỉ sự hoàn thành</h2><div class="pattern">Chủ ngữ + động từ + tân ngữ + 了</div>${grammarExamples([["我买衣服了。／我去图书馆了。","Wǒ mǎi yīfu le. / Wǒ qù túshūguǎn le.","Tôi đã mua quần áo. / Tôi đã đến thư viện."]])}<div class="pattern">Chủ ngữ + động từ + 了 + tân ngữ có bổ nghĩa</div>${grammarExamples([["我买了一件衬衫和一双鞋。","Wǒ mǎile yí jiàn chènshān hé yì shuāng xié.","Tôi đã mua một chiếc áo sơ mi và một đôi giày."],["我看了一个中国电影。","Wǒ kànle yí ge Zhōngguó diànyǐng.","Tôi đã xem một bộ phim Trung Quốc."]])}<p class="sub">了 nhấn mạnh việc xảy ra hoặc hoàn thành; không tự động thêm vào mọi câu chỉ vì có thời gian quá khứ.</p></article><article class="card grammar"><h2>02 · Ba cách hỏi</h2>${grammarExamples([["你吃饭了吗？","Nǐ chī fàn le ma?","Bạn ăn cơm chưa?"],["你吃饭了没有？","Nǐ chī fàn le méiyǒu?","Bạn ăn cơm chưa?"],["你吃没吃饭？","Nǐ chī méi chī fàn?","Bạn ăn cơm chưa?"]])}${grammarExamples([["你昨天打球了吗？","Nǐ zuótiān dǎ qiú le ma?","Hôm qua bạn có chơi bóng không?"],["你昨天打球了没有？","Nǐ zuótiān dǎ qiú le méiyǒu?","Hôm qua bạn có chơi bóng không?"],["你昨天打没打球？","Nǐ zuótiān dǎ méi dǎ qiú?","Hôm qua bạn có chơi bóng không?"]])}</article><article class="card grammar"><h2>03 · Phủ định bằng 没</h2><div class="pattern">Chủ ngữ + 没（有） + động từ + tân ngữ</div><p>Trong mẫu phủ định việc chưa hoặc không xảy ra của bài, bỏ 了.</p>${grammarExamples([["我没吃早饭。","Wǒ méi chī zǎofàn.","Tôi chưa ăn sáng."],["我没打球。","Wǒ méi dǎ qiú.","Tôi không chơi bóng."],["上个星期我没买衣服。","Shàng ge xīngqī wǒ méi mǎi yīfu.","Tuần trước tôi không mua quần áo."]])}</article><article class="card grammar"><h2>04 · Câu vị ngữ chủ vị</h2><div class="pattern">Chủ đề + [chủ ngữ nhỏ + vị ngữ]</div>${grammarExamples([["北京博物馆很多，公园不多。","Běijīng bówùguǎn hěn duō, gōngyuán bù duō.","Bắc Kinh có nhiều bảo tàng, không nhiều công viên."],["那个博物馆东西很多，人不多。","Nà ge bówùguǎn dōngxi hěn duō, rén bù duō.","Bảo tàng đó có nhiều đồ, không nhiều người."],["他汉语很好，英语不好。","Tā Hànyǔ hěn hǎo, Yīngyǔ bù hǎo.","Tiếng Trung của anh ấy tốt, tiếng Anh không tốt."]])}<p class="sub">Phủ định đặt trước vị ngữ nhỏ.</p></article><a class="btn" href="#practice">Luyện câu hỏi và trả lời →</a>`+lesson6References(3,5);}
